{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required = set(case.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}
    retained = set()

    def retain_with_ancestors(node_id):
        seen = set()
        while node_id is not None and node_id not in seen and node_id in by_id:
            seen.add(node_id)
            retained.add(node_id)
            node_id = by_id[node_id].get("parent")

    # Nodes that cannot be removed, and their structural context, are mandatory.
    for node in nodes:
        if not node.get("removable", False):
            retain_with_ancestors(node["id"])

    # Ensure each required symbol has a retained representative. Prefer the
    # highest-utility candidate, with input order providing deterministic ties.
    present = {by_id[node_id].get("symbol") for node_id in retained}
    for symbol in required:
        if symbol not in present:
            candidates = [node for node in nodes if node.get("symbol") == symbol]
            if candidates:
                best = max(candidates, key=lambda node: node.get("utility", 0))
                retain_with_ancestors(best["id"])
                present.add(symbol)

    retained_node_ids = [node["id"] for node in nodes if node["id"] in retained]
    removed_node_ids = [
        node["id"] for node in nodes
        if node["id"] not in retained and node.get("removable", False)
    ]
    return {
        "removed_node_ids": removed_node_ids,
        "retained_node_ids": retained_node_ids,
    }
"}
